RestServiceDefinition.SqlExecute:
  CREATE TABLE IF NOT EXISTS useraccesspackage (
  id TEXT, accessPackage_id TEXT, target_principalName TEXT
  );

        SELECT useraccesspackage.id,
     target_principalName as UserName,
     accessPackagesCatalogs.displayName || '/' || accessPackages.displayName as RoleName
FROM useraccesspackage
inner join accessPackages on accessPackages.id = useraccesspackage.accessPackage_id 
inner join accessPackagesCatalogs on accessPackagesCatalogs.id = accessPackages.catalog_id ;
